from __future__ import annotations

__doc__ = """Helpers for assembling and manipulating coupled multi-spin systems."""

import numpy as np
from scipy.spatial.transform import Rotation
from itertools import combinations

ZEROTOL = 1e-14


class Vector:
    """A class to store and manage a position"""

    def __init__(self, *components, dim=None):
        if dim is None:
            dim = len(components)
        else:
            if not len(components) == dim:
                raise ValueError("components and dimension do not match")
        self._dim = dim
        self._cmp = components

    def make_compatible(self, other):
        """check the compatibility between two positions"""
        if other is None:
            return Vector(*[0 for _ in range(self._dim)])
        if self.dim == other.dim:
            return other
        raise ValueError("cannot add incompatible vectors")

    def __str__(self):
        return str(self.as_tuple())

    def __repr__(self):
        return str(self.as_tuple())

    @property
    def dim(self):
        """request the dimension of this position"""
        return self._dim

    @property
    def components(self):
        """access the individual components"""
        yield from self._cmp

    def distance(self, other):
        """
        Compute the distance between this and another position.
        Defaults to euclidean distance.
        """
        other = self.make_compatible(other)
        if not other:
            raise ValueError("positions not compatible for distance measure")
        r2 = sum(
            (c1 - c2) ** 2 for c1, c2 in zip(self.components, other.components)
        )
        return np.sqrt(r2)

    def origin(self):
        """return an origin instance in the format of this vector"""
        return type(self)(*[0 for _ in range(self.dim)])

    @classmethod
    def get_cms(cls, *pos_weight_pairs):
        """get the center of mass"""
        if not pos_weight_pairs:
            raise ValueError("cannot compute CMS from empty list")
        if not isinstance(pos_weight_pairs[0], tuple):
            return cls.get_cms(*[(pos, 1) for pos in pos_weight_pairs])
        accum_pos = None
        accum_wgh = 0.0
        for pos, weight in pos_weight_pairs:
            if accum_pos is None:
                accum_pos = pos.origin()
            accum_pos += pos * weight
            accum_wgh += weight
        return accum_pos / accum_wgh

    @staticmethod
    def get_rot_matrix(angle, axis=None, degrees=False):
        """compute a rotation matrix for the vector"""
        if axis.dim == 2:
            if degrees:
                angle = np.deg2rad(angle)
            return np.array(
                [
                    [np.cos(angle), np.sin(angle)],
                    [-np.sin(angle), np.cos(angle)],
                ]
            )
        assert axis.dim == 3
        rotation = Rotation.from_rotvec(
            (angle * axis / abs(axis)).as_tuple(), degrees=degrees
        )
        # avoid numpy stuff here
        return [Vector(*map(float, line)) for line in rotation.as_matrix()]

    def scalar_product(self, other):
        """compute the scalar product of two vectors"""
        if not isinstance(other, Vector):
            other = Vector(*other)
        return sum(
            (cp * ot for cp, ot in zip(self.components, other.components))
        )

    def matrix_transform(self, matrix):
        """perform a matrix transform"""
        return type(self)(*[self.scalar_product(line) for line in matrix])

    def scale(self, alpha, offset=None):
        """scale the position w.r.t. reference. The reference defaults to the origin"""
        if offset is None:
            offset = self.origin()
        if not isinstance(offset, Vector):
            offset = Vector(*offset)
        return offset + alpha * (self - offset)

    def translate(self, vector):
        """translate a vector by another"""
        if not isinstance(vector, Vector):
            vector = Vector(*vector)
        return self + vector

    def rotate(self, angle, axis=None, offset=None, degrees=False):
        """rotate a position vector by an angle around an axis at an offset"""
        if offset is None:
            offset = self.origin()
        if not isinstance(offset, Vector):
            offset = Vector(*offset)
        if self.dim == 2:
            axis = Vector(0, 0)
        else:
            assert axis is not None
        if not isinstance(axis, Vector):
            axis = Vector(*axis)
        rot_mat = self.get_rot_matrix(angle, axis, degrees=degrees)
        return offset + (self - offset).matrix_transform(rot_mat)

    # provide some basic vector operations

    def __add__(self, other):
        # if other is None:
        #     other = tuple(*[0 for _ in range(self.dim)])
        other = self.make_compatible(other)
        return type(self)(
            *[cp + ot for cp, ot in zip(self.components, other.components)]
        )

    def __sub__(self, other):
        # if other is None:
        #     other = tuple(*[0 for _ in range(self.dim)])
        other = self.make_compatible(other)
        return type(self)(
            *[cp - ot for cp, ot in zip(self.components, other.components)]
        )

    def __abs__(self):
        return self.distance(self.origin())

    def __mul__(self, other):
        assert not isinstance(other, Vector)
        return type(self)(*[cp * other for cp in self.components])

    def __rmul__(self, other):
        assert not isinstance(other, Vector)
        return type(self)(*[cp * other for cp in self.components])

    def __truediv__(self, other):
        assert not isinstance(other, Vector)
        return type(self)(*[cp / other for cp in self.components])

    def __iter__(self):
        # allows list conversion, ...
        yield from map(float, self._cmp)

    def as_tuple(self):
        """convert to a component tuple"""
        return tuple(self)


class Unit:
    """a simple unit, acts as a system building block"""

    _counter = 0
    _species = "UNIT"

    def __init__(self, *, name=None, **kwargs):
        count = type(self)._counter
        self._idx = count
        if name is None:
            name = f"{type(self)._species}_{count}"
        type(self)._counter += 1
        self._enum = count
        self._name = name
        self._parent = None
        super().__init__()

    def content(
        self,
        **_,
    ):
        """access read-only property content"""
        yield self

    def level(self):
        """recursively compute the level of the unit. The default is a recursive break"""
        return 0

    def _get_gen_dict(self):
        return {"name": self._name}

    def copy(self, name=None):
        """make a copy of self"""
        if name is None:
            name = self.name
        obj = type(self)(**{**self._get_gen_dict(), "name": name})
        return obj

    @property
    def name(self):
        """read-only access to attribute name"""
        return self._name

    def __init_subclass__(cls, species=None):
        if species is None:
            species = cls.__name__.upper()
        if not isinstance(species, str):
            raise TypeError("species must be a string")
        cls._species = species
        cls._counter = 0

    @classmethod
    def new_species(cls, species, *co_classes):
        """derive a new species"""
        if co_classes and __debug__:
            print(
                "the use of co-classes is highly discouraged. But you do you."
            )
        return type(
            species,
            (*co_classes, cls),
            {},
        )

    def __gt__(self, other):
        if self.species == other.species:
            return self.index > other.index
        return self.species > other.species

    @property
    def species(self):
        """read-only access to class attribute species"""
        return type(self)._species

    @property
    def index(self):
        """read-only access to attribute index"""
        return self._idx

    @property
    def parent(self):
        """read-only access to attribute parent"""
        return self._parent

    def set_parent(self, parent, overwrite=False):
        """set the parent. Make sure parent is not set or allow overwrite"""
        if self._parent is not None:
            if not overwrite:
                raise ValueError("parent already set")
        if parent is self:
            raise ValueError("parent cannot point to self")
        if parent is not None:
            if self in parent.get_family_tree():
                raise ValueError("cyclic family trees are not allowed")
        self._parent = parent

    def get_family_tree(self):
        """create a family tree"""
        if self.parent is not None:
            yield from self.parent.get_family_tree()
        yield self

    def __str__(self):
        name = ".".join(obj.name for obj in self.get_family_tree())
        return f"<{name}[{self._enum}]>"  # @{self.position()}>"

    def __repr__(self):
        return f"<{self.name}>"


class Group(Unit, species="GROUP"):
    """A class to have a group of either spins or other groups"""

    def __init__(self, *units, **kwargs):
        self._content = []
        super().__init__(**kwargs)
        for unit in units:
            self.append(unit)

    def level(self):
        """recursively compute the level of the unit. The default is a recursive break"""
        if self._content:
            return 1 + max(con.level() for con in self._content)
        return 0

    def apply(self, key, *args, **kwargs):
        """apply a transform or operation"""
        for con in self.content():
            con.apply(key, *args, **kwargs)

    def content(
        self,
        *,
        recursive=False,
    ):
        """access read-only property content"""
        if recursive:
            for unit in self._content:
                yield from unit.content(recursive=True)
        else:
            for unit in self._content:
                yield unit

    def units(self):
        """Yield all spins in a deterministic order."""
        yield from self.content(recursive=True)

    def copy(self, name=None):
        if name is None:
            name = self.name
        obj = type(self)(**(self._get_gen_dict() | {"name": name}))
        for con in self._content:
            con_copy = con.copy()
            obj.append(con_copy)
        return obj

    def append(self, *units):
        """append to a group"""
        # automatically break collectives in groups
        for unit in units:
            unit.set_parent(self)
            self._content.append(unit)
        return self

    def __iter__(self):
        yield from self.content(recursive=False)


class Single(Unit, species="SINGLE"):
    """
    A class for a single spin.

    Currently implemented as a subclass of Unit, but I consider to implemented
    as a trivial group of size 1
    """

    def content(
        self,
        **_,
    ):
        """recursion break"""
        yield self

    def append(self, *units, **_):
        """Singles cannot contain child units"""
        raise TypeError("Cannot append to a Single")


