class _MixIn(Unit):
    def _get_gen_dict(self):
        return {}


class Nuclear(_MixIn):
    """Introduce features relevant for nuclear spins"""

    def __init__(self, *, gamma=1.0, spin2=1, **kwargs):
        self._gamma = gamma  # gyromagnetic ratio
        self._spin2 = spin2  # the spin number as a multiple of 1/2
        super().__init__(**kwargs)

    def _get_gen_dict(self):
        return super()._get_gen_dict() | {
            "gamma": self._gamma,
            "spin2": self._spin2,
        }

    def gamma(self):
        """get the value for the gyromagnetic ratio gamma"""
        return self._gamma

    def spin_half(self):
        """get the value for the spin number as a multiple of 1/2. For spin-3/2, the value is 3"""
        return self._spin2


class SpatialPosition(_MixIn):
    """summarize functionality for spatial positions"""

    _dim = None

    def __init__(self, *, pos=None, **kwargs):
        pos = self._pos_to_vec(pos)
        self._pos = pos
        super().__init__(**kwargs)

    def _get_gen_dict(self):
        return super()._get_gen_dict() | {"pos": self._pos}

    def _pos_to_vec(self, pos):
        if isinstance(pos, Vector):
            if pos.dim != self._dim:
                raise ValueError("Dimension mismatch")
        if pos is not None:
            return Vector(*pos, dim=type(self)._dim)
        if type(self)._dim is None:
            return None
        return Vector(
            *[0 for _ in range(type(self)._dim)], dim=type(self)._dim
        )

    def apply(self, key, *args, **kwargs):
        """apply a transform or operation"""
        match key:
            case "scale":
                return self.scale(*args, **kwargs)
            case "translate":
                return self.translate(*args, **kwargs)
            case "rotate":
                return self.rotate(*args, **kwargs)

        if not hasattr(self, "apply"):
            raise TypeError(
                "apply is only provided if you inherit from a unit!"
            )
        return super().apply(key, *args, **kwargs)

    def position(self, wrt=None):
        """read-only access to attribute position"""
        if wrt is None:
            return self._pos
        return self.position() - wrt.position()

    def distance(self, other):
        """compute the distance between this spin and another"""
        assert isinstance(self.position(), Vector)
        assert isinstance(other.position(), Vector)
        return self.position().distance(other.position())

    def scale(self, alpha, offset=None):
        """implement a scaling of the positions"""
        if self._pos is not None:
            self._pos = self._pos.scale(alpha, offset=offset)
        return self

    def translate(self, vector):
        """implement a translation by a vector"""
        if self._pos is not None:
            self._pos = self._pos.translate(vector)
        return self

    def rotate(self, angle, axis=None, offset=None, degrees=False):
        """implement a rotation around a given axis at an offset by an angle"""
        if self._pos is not None:
            self._pos = self._pos.rotate(
                angle, axis=axis, offset=offset, degrees=degrees
            )
        return self


class SpatialPosition3D(SpatialPosition):
    """explicitely use 3 dimensions"""

    _dim = 3


class SpatialPosition2D(SpatialPosition):
    """explicitely use 2 dimensions"""

    _dim = 2


class SpatialPosition1D(SpatialPosition):
    """explicitely use 1 dimension"""

    _dim = 1


class System:
    """Root object for a hierarchy of local sites and Hamiltonian helpers."""

    def __init__(self, units, hamiltonian=None, **properties):
        self._units = units
        self._hamiltonian = hamiltonian
        self._properties = properties

    def __getitem__(self, key):
        return self._properties.get(key, None)

    def units(self):
        yield from self._units.units()

    def unit_index_map(self):
        """Map local sites to dense tensor-product indices."""
        return {unit: idx for idx, unit in enumerate(self.units())}

    def pair_iter(self, *, excludes=None, considers=None):
        """Iterate over spin pairs with optional geometric filtering."""
        if excludes is None:
            excludes = []
        if considers is None:
            considers = []
        for unit_a, unit_b in combinations(self.units(), 2):
            if any(not consider(unit_a, unit_b) for consider in considers):
                continue
            if any(exclude(unit_a, unit_b) for exclude in excludes):
                continue
            yield unit_a, unit_b

    def create_hamiltonian(self, name="hamiltonian"):
        """Create a Hamiltonian bound to this system."""
        return Hamiltonian(system=self, name=name)


class HamiltonianTerm:
    """A generic Hamiltonian term acting on a system."""

    _KIND: str = "generic"
    __slots__ = (
        "_units",
        "_coefficient",
        "_specifier",
        "_system",
        "_metadata",
    )

    def __init__(self, units, coefficient, specifier, system, **metadata):
        self._units = units
        self._coefficient = coefficient
        self._specifier = specifier
        self._system = system
        self._metadata = metadata

    @property
    def units(self):
        return self._units

    @property
    def coefficient(self):
        return self._coefficient

    @property
    def specifier(self):
        return self._specifier

    @property
    def system(self):
        return self._system

    @property
    def kind(self):
        return type(self)._KIND

    def __gt__(self, other: HamiltonianTerm) -> bool:
        if len(self._units) < len(other._units):
            return False
        if len(self._units) > len(other._units):
            return True

        assert len(self._units) == len(other._units)
        if self._units > other._units:
            return True
        if self._units < other._units:
            return False

        if self._coefficient > other._coefficient:
            return True
        return False

    def __eq__(self, other: HamiltonianTerm) -> bool:
        if self._units != other._units:
            return False
        if callable(self.coefficient) or callable(other.coefficient):
            raise TypeError(
                "Cannot compare HamiltonianTerm with callable coefficients"
            )
        if abs(self.coefficient - other.coefficient) < ZEROTOL:
            return True
        return False

    def _evaluate_coeff(self, time=0.0, system=None):
        """Evaluate the coefficient, including dynamic callables."""
        coeff = self.coefficient
        if callable(coeff):
            return coeff(time, system, self)
        return coeff

    def fix(self, time=0.0, system=None):
        coeff = self._evaluate_coeff(time=time, system=system)
        return HamiltonianTerm(
            units=self.units,
            coefficient=coeff,
            specifier=self.specifier,
            system=self.system,
        )


class Hamiltonian:
    """Sparse symbolic Hamiltonian with optional explicit matrix terms."""

    def __init__(self, *terms, system=None, name="hamiltonian"):
        if system is None:
            raise ValueError("system must be specified")
        self._system = system
        self._name = name
        self._terms = []
        self.extend(*terms)

    @property
    def system(self):
        return self._system

    @property
    def name(self):
        return self._name

    @property
    def terms(self):
        return tuple(self._terms)

    def copy(self, name=None):
        clone = type(self)(
            *self.terms,
            system=self.system,
            name=self.name if name is None else name,
        )
        clone._terms = list(self._terms)
        return clone

    def extend(self, *terms):
        """add one or more terms to the hamiltonian"""
        for term in terms:
            if not isinstance(term, HamiltonianTerm):
                raise TypeError(
                    "can only append HamiltonianTerm to Hamiltonian"
                )
            self._terms.append(term)

        return self


